import{H as e,V as t,et as n,j as r}from"./chunks/framework.JoxZRDkC.js";var i=JSON.parse(`{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}`),a={name:`architecture.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to “Architecture Overview”">​</a></h1><p>This document describes the high-level architecture and design of <code>@chitrank2050/ask-widget</code>.</p><h2 id="component-layer" tabindex="-1">Component Layer <a class="header-anchor" href="#component-layer" aria-label="Permalink to “Component Layer”">​</a></h2><p>The main entry point is the <code>ChatWidget</code> component. It renders a floating chat action button and a collapsible chat panel containing:</p><ul><li><strong>Message List</strong>: Renders conversation history with support for styling code snippets and user/assistant message variants.</li><li><strong>Input Area</strong>: Captures user text and manages the submission state.</li></ul><h2 id="state-hooks-layer-headless-api" tabindex="-1">State &amp; Hooks Layer (Headless API) <a class="header-anchor" href="#state-hooks-layer-headless-api" aria-label="Permalink to “State &amp; Hooks Layer (Headless API)”">​</a></h2><p>The business logic is decoupled from the UI using custom hooks:</p><ul><li><code>useChat</code>: Manages state for the conversation (messages array, loading state, input state).</li><li><code>useSSEStream</code>: Connects to the SSE streaming API and streams tokens sequentially.</li><li><code>useSession</code>: Manages state persistence across page reloads (using <code>sessionStorage</code> or <code>localStorage</code>).</li></ul><h2 id="style-presentation-layer" tabindex="-1">Style &amp; Presentation Layer <a class="header-anchor" href="#style-presentation-layer" aria-label="Permalink to “Style &amp; Presentation Layer”">​</a></h2><p>The UI is styled using Vanilla CSS with CSS Cascade Layers (<code>@layer</code>) to guarantee style encapsulation and prevent styles from leaking into the parent page (host application). Variables are driven by HSL tokens conforming to the neutral zinc palette.</p>`,10)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};